parameters.jsCode:
// Primera barrera del chat. El nodo JWT ya verificó firma y vencimiento.
// Aquí se valida la identidad, se limpian datos personales y se bloquean
// intentos de inyección, consultas sobre otros estudiantes y SQL.
const EMISOR = 'chatbot-unab-api';
const AUDIENCIA = 'chatbot-unab';
const MAX_CARACTERES = 1500;

const claims = $input.first().json.payload ?? {};
const body = $('Recibir pregunta').first().json.body ?? {};

const audienciaValida = Array.isArray(claims.aud) ? claims.aud.includes(AUDIENCIA) : claims.aud === AUDIENCIA;
const codigo = String(claims.sub ?? '');
if (claims.iss !== EMISOR || !audienciaValida || !/^U00\d{6}$/.test(codigo)) {
  throw new Error('Token de sesión con emisor, audiencia o código no válidos');
}

const sesionId = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(body.sesion_id ?? ''))
  ? body.sesion_id
  : null;

let pregunta = String(body.mensaje ?? '').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '').trim();
const avisos = [];
const eventos = [];
if (pregunta.length > MAX_CARACTERES) {
  pregunta = pregunta.slice(0, MAX_CARACTERES);
  avisos.push('mensaje_recortado');
}

// Datos personales: se ocultan antes de llegar al modelo y a la base de datos
const DATOS_PERSONALES = [
  ['correo', /[\w.+-]+@[\w-]+(\.[\w-]+)+/g, '[correo oculto]'],
  ['tarjeta', /\b(?:\d[ -]?){13,19}\b/g, '[número oculto]'],
  ['documento_o_telefono', /\b\d{8,12}\b/g, '[número oculto]'],
];
const ocultos = [];
for (const [campo, patron, reemplazo] of DATOS_PERSONALES) {
  if (patron.test(pregunta)) {
    ocultos.push(campo);
    pregunta = pregunta.replace(patron, reemplazo);
  }
}
if (ocultos.length) {
  eventos.push({ tipo: 'datos_personales', detalle: { origen: 'pregunta', campos: ocultos } });
  avisos.push('datos_personales_ocultos');
}

const INYECCION = [
  /ignor(a|ar|e)\s+(todas?\s+)?(las\s+|tus\s+|mis\s+)?(instrucciones|reglas|indicaciones)/i,
  /olvid(a|ar)\s+(todo|tus\s+(instrucciones|reglas))/i,
  /(prompt|mensaje|instrucciones)\s+(del\s+)?sistema/i,
  /system\s*prompt/i,
  /ignore\s+(all\s+|any\s+)?(previous|prior|above)\s+(instructions|rules)/i,
  /\b(act[uú]a|comp[oó]rtate|finge)\s+(como|que\s+eres)\s+(si\s+fueras\s+)?(un\s+|el\s+)?(administrador|desarrollador|root|programador del sistema)/i,
  /\b(jailbreak|modo\s+desarrollador|developer\s+mode)\b/i,
  /(revela|muestra|imprime|dime|escribe)\s+(tu|el|tus)\s+(prompt|configuraci[oó]n|instrucciones)/i,
  /<\/?\s*(system|instrucciones|assistant|tool)\s*>/i,
  /\b(api[\s_-]?key|token\s+de\s+servicio|contrase[nñ]a\s+de\s+la\s+base|jwt_secret)\b/i,
];
const SQL = [
  /;\s*(drop|delete|update|insert|alter|truncate|grant|revoke|create)\s/i,
  /\bunion\s+(all\s+)?select\b/i,
  /\b(drop|truncate|alter)\s+table\b/i,
  /\bdelete\s+from\b/i,
  /'\s*or\s+'?1'?\s*=\s*'?1/i,
  /\bselect\s+[\w*,\s]+\s+from\s+\w+/i,
];
const otrosCodigos = [...new Set([...pregunta.toUpperCase().matchAll(/U00\d{6}/g)].map((m) => m[0]))]
  .filter((c) => c !== codigo);

let bloqueo = null;
if (!pregunta) {
  bloqueo = { tipo: null, respuesta: 'Escribe tu pregunta y con gusto te ayudo.' };
} else if (otrosCodigos.length) {
  bloqueo = {
    tipo: 'acceso_no_autorizado',
    detalle: { motivo: 'consulta sobre otro estudiante', codigos: otrosCodigos.length },
    respuesta: 'Por seguridad solo puedo mostrarte tu propia información académica. No puedo consultar datos de otros estudiantes.',
  };
} else if (INYECCION.some((p) => p.test(pregunta))) {
  bloqueo = {
    tipo: 'prompt_injection',
    detalle: { categoria: 'instrucciones' },
    respuesta: 'No puedo cambiar mis instrucciones ni compartir mi configuración. Sí puedo ayudarte con los cursos de competencias digitales, tu progreso, el calendario académico y los reglamentos.',
  };
} else if (SQL.some((p) => p.test(pregunta))) {
  bloqueo = {
    tipo: 'prompt_injection',
    detalle: { categoria: 'sql_peligroso' },
    respuesta: 'No ejecuto consultas escritas en el chat. Pregúntame en lenguaje natural, por ejemplo: "¿qué cursos tengo aprobados?".',
  };
}
if (bloqueo?.tipo) {
  eventos.push({ tipo: bloqueo.tipo, detalle: bloqueo.detalle });
}

return [{
  json: {
    inicio: Date.now(),
    codigo,
    sesion_id: sesionId,
    pregunta: pregunta || '(mensaje vacío)',
    bloqueado: Boolean(bloqueo),
    respuesta_bloqueo: bloqueo?.respuesta ?? null,
    avisos,
    eventos,
  },
}];

// Respuesta segura para un mensaje bloqueado por el guardrail de entrada
const guardrail = $('Guardrail de entrada').first().json;

return [{
  json: {
    respuesta: guardrail.respuesta_bloqueo,
    intencion: null,
    intenciones: [],
    fuentes: [],
    herramientas: [],
    bloqueado: true,
    eventos: guardrail.eventos,
  },
}];

