// Si el clasificador falla (por ejemplo, el modelo no responde), se sigue
// con una clasificación general y el agente decide qué herramientas usar.
const guardrail = $('Guardrail de entrada').first().json;

return [{
  json: {
    output: {
      intenciones: ['academica_general'],
      consulta_busqueda: guardrail.pregunta,
      fuera_de_alcance: false,
      motivo: 'clasificación por defecto: el clasificador no respondió',
    },
  },
}];

// Respuesta para preguntas que no son académicas
const guardrail = $('Guardrail de entrada').first().json;
const clasificacion = $input.first().json.output ?? {};
const perfil = $('Iniciar turno').first().json.perfil ?? {};

return [{
  json: {
    respuesta: `${perfil.nombre ? perfil.nombre + ', ' : ''}esa pregunta está fuera de lo que puedo responder. Soy el asistente académico de Ingeniería de Sistemas: puedo ayudarte con los cursos de competencias digitales y la insignia, tu historial y progreso, el calendario académico, los reglamentos y las novedades. ¿En qué de eso te ayudo?`,
    intencion: 'fuera_de_alcance',
    intenciones: ['fuera_de_alcance'],
    fuentes: [],
    herramientas: [],
    bloqueado: false,
    eventos: [
      ...guardrail.eventos,
      { tipo: 'fuera_de_alcance', detalle: { motivo: String(clasificacion.motivo ?? '').slice(0, 200) } },
    ],
  },
}];

// Segunda barrera: revisa la respuesta del agente antes de entregarla.
// 0) Si el agente falló, responde con un mensaje de contingencia.
// 1) Oculta tokens, claves, correos de estudiantes y códigos ajenos.
// 2) Si da datos concretos sin haber usado ninguna herramienta, se reemplaza
//    por una respuesta segura (reducción de alucinaciones).
// 3) Arma las fuentes que la app muestra debajo de la respuesta.
const agente = $input.first().json;
const guardrail = $('Guardrail de entrada').first().json;
const clasificacion = $('¿Fuera de alcance?').first().json.output ?? {};

const INTENCIONES = ['academica_general', 'documental', 'calendario', 'historial', 'noticias', 'recomendacion'];
const intenciones = (clasificacion.intenciones ?? []).filter((i) => INTENCIONES.includes(i));
const intencion = intenciones[0] ?? 'academica_general';

// Contingencia: el agente o el modelo fallaron (sin respuesta de texto)
if (agente.error || typeof agente.output !== 'string') {
  return [{
    json: {
      respuesta: 'En este momento no pude consultar mis fuentes. Intenta de nuevo en unos minutos.',
      intencion,
      intenciones,
      fuentes: [],
      herramientas: [],
      bloqueado: false,
      validada: false,
      eventos: guardrail.eventos,
    },
  }];
}

// Herramientas usadas y fuentes documentales
const pasos = agente.intermediateSteps ?? [];
const herramientas = [...new Set(pasos.map((p) => p.action?.tool).filter(Boolean))];

const leer = (observacion) => {
  try {
    const valor = typeof observacion === 'string' ? JSON.parse(observacion) : observacion;
    return Array.isArray(valor) ? valor : [valor];
  } catch {
    return [];
  }
};

let fuentes = [];
const vistas = new Set();
for (const paso of pasos) {
  if (paso.action?.tool !== 'buscar_documentos') continue;
  for (const resultado of leer(paso.observation)) {
    for (const f of (resultado?.fragmentos ?? resultado?.json?.fragmentos ?? [])) {
      const clave = `${f.archivo}|${f.pagina ?? ''}`;
      if (vistas.has(clave)) continue;
      vistas.add(clave);
      fuentes.push({
        tipo: 'documento',
        titulo: f.documento,
        archivo: f.archivo,
        pagina: f.pagina ?? null,
        seccion: f.seccion ?? null,
        url: f.url ?? null,
        origen: f.origen,
        similitud: f.similitud,
      });
    }
  }
}
fuentes.sort((a, b) => (b.similitud ?? 0) - (a.similitud ?? 0));
fuentes = fuentes.slice(0, 4);
// Las demás herramientas cuentan como fuente solo si respondieron sin error
const respondio = (herramienta) => pasos.some((p) => p.action?.tool === herramienta
  && leer(p.observation).some((r) => r && !r.error && !r.json?.error));
if (respondio('consultar_calendario')) {
  fuentes.push({ tipo: 'calendario', titulo: 'Calendario académico (Google Sheets)', origen: 'demostrativo' });
}
if (respondio('consultar_mis_datos')) {
  fuentes.push({ tipo: 'historial', titulo: 'Historial académico (servidor MCP)', origen: 'demostrativo' });
}
if (respondio('consultar_noticias')) {
  fuentes.push({ tipo: 'noticias', titulo: 'Noticias y convocatorias recopiladas', origen: 'publico' });
}

// Limpieza de datos sensibles en la respuesta
let texto = String(agente.output ?? '').trim();
const eventos = [...guardrail.eventos];
const hallazgos = [];
const ocultar = (patron, etiqueta) => {
  if (patron.test(texto)) {
    hallazgos.push(etiqueta);
    texto = texto.replace(patron, '[dato oculto]');
  }
};
ocultar(/eyJ[\w-]{10,}\.[\w-]{10,}\.[\w-]{10,}/g, 'token');
ocultar(/\b(sk-ant-|sk-|pa-)[\w-]{16,}/g, 'clave');
ocultar(/postgres(ql)?:\/\/\S+/gi, 'cadena_conexion');
ocultar(/[\w.+-]+@demo\.local\b/gi, 'correo_estudiante');
for (const otro of new Set([...texto.matchAll(/U00\d{6}/g)].map((m) => m[0]))) {
  if (otro !== guardrail.codigo) {
    hallazgos.push('codigo_estudiante');
    texto = texto.replaceAll(otro, '[dato oculto]');
  }
}
if (hallazgos.length) {
  eventos.push({ tipo: 'datos_personales', detalle: { origen: 'respuesta', hallazgos } });
}

// Datos concretos (fechas, NRC, notas) sin respaldo de una herramienta
let validada = true;
const DATOS_CONCRETOS = /\b\d{4}-\d{2}-\d{2}\b|\b\d{1,2}\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)\b|\bNRC\b|\b\d{5}\b|\bnota\s+(de\s+)?\d/i;
if (herramientas.length === 0 && DATOS_CONCRETOS.test(texto)) {
  validada = false;
  eventos.push({ tipo: 'respuesta_no_validada', detalle: { motivo: 'datos concretos sin consultar fuentes' } });
  texto = 'No pude confirmar esa información en las fuentes disponibles y prefiero no darte un dato que podría ser incorrecto. Intenta preguntarlo de otra forma o consulta con la coordinación de tu programa.';
}
if (intenciones.includes('documental') && !herramientas.includes('buscar_documentos')) {
  eventos.push({ tipo: 'respuesta_no_validada', detalle: { motivo: 'pregunta documental respondida sin buscar en documentos' } });
}
if (!texto) {
  validada = false;
  texto = 'No pude generar una respuesta en este momento. Intenta de nuevo en unos segundos.';
}
if (texto.length > 3500) {
  texto = texto.slice(0, 3500) + '…';
}

return [{
  json: {
    respuesta: texto,
    intencion,
    intenciones,
    fuentes,
    herramientas,
    bloqueado: false,
    validada,
    eventos,
  },
}];

// Punto de encuentro de las cuatro ramas (bloqueo, fuera de alcance,
// agente y contingencia): todas entregan la misma estructura.
const r = $input.first().json;

return [{
  json: {
    respuesta: r.respuesta,
    intencion: r.intencion ?? null,
    intenciones: r.intenciones ?? [],
    fuentes: r.fuentes ?? [],
    herramientas: r.herramientas ?? [],
    bloqueado: r.bloqueado === true,
    validada: r.validada ?? true,
    eventos: r.eventos ?? [],
  },
}];
